"""IR -> standalone PyAEDT script (HFSS). The script builds, solves, and writes s11.csv (f_GHz,re,im)."""
from __future__ import annotations

from .model import Bool, Box, Cyl, Model

HEADER = '''\
"""Generated by antenna_agent. Requires ANSYS Electronics Desktop + pyaedt (ansys-aedt-core)."""
import csv, os, sys
from pathlib import Path

# HFSS Student 2025 R2: le transport gRPC par defaut (WNUA) echoue -> forcer l'ancien mode
# (PyAEDT issue #7842 + Troubleshooting). Doit etre fait avant tout lancement.
if os.environ.get("AEDT_STUDENT", "0") == "1":
    os.environ.setdefault("PYAEDT_USE_PRE_GRPC_ARGS", "True")

try:
    from ansys.aedt.core import Hfss          # pyaedt >= 0.9
except ImportError:
    from pyaedt import Hfss                    # older releases

OUT = Path(sys.argv[1] if len(sys.argv) > 1 else ".").resolve()
OUT.mkdir(parents=True, exist_ok=True)
VERSION = os.environ.get("AEDT_VERSION") or None        # e.g. "2025.1"
NON_GRAPHICAL = os.environ.get("AEDT_GUI", "0") != "1"

try:  # HFSS Student can take minutes to start: give PyAEDT a long launch timeout (seconds, env AEDT_TIMEOUT)
    from ansys.aedt.core.generic.settings import settings as _pyaedt_settings
    if os.environ.get('AEDT_SECURE','0')!='1':
        _pyaedt_settings.grpc_secure_mode = False  # WNUA echoue avec HFSS Student
    _pyaedt_settings.desktop_launch_timeout = int(os.environ.get("AEDT_TIMEOUT", "300"))
    if os.environ.get("AEDT_COM", "0") == "1":   # mode COM (sans gRPC): lance ansysedtsv.exe sans argument
        _pyaedt_settings.use_grpc_api = False
except Exception:
    pass


def open_hfss():
    kw = dict(project=str(OUT / "antenna.aedt"), design="antenna", solution_type="Modal",
              version=VERSION, non_graphical=NON_GRAPHICAL,
              student_version=os.environ.get("AEDT_STUDENT", "0") == "1")
    port = os.environ.get("AEDT_PORT")                     # attach to an AEDT started by hand with -grpcsrv <port>
    if port:
        kw["port"] = int(port)
    for flag in ("new_desktop", "new_desktop_session"):    # kwarg was renamed between releases
        try:
            return Hfss(**kw, **{flag: not port})
        except TypeError:
            continue
    raise RuntimeError("unsupported pyaedt Hfss() signature")


hfss = open_hfss()
try:
    hfss.modeler.model_units = "mm"
'''

FOOTER = '''
    # ---- results (API robuste: pyaedt >= 1.x utilise get_expression_data, avant data_real/data_imag)
    def _col(sd, expr, kind):
        if hasattr(sd, "get_expression_data"):
            return list(sd.get_expression_data(expression=expr, formula=kind)[1])
        return list(sd.data_real(expr) if kind == "real" else sd.data_imag(expr))

    setup_sweep = f"Setup1 : {sweep.name}"
    sol = hfss.post.get_solution_data(expressions=["S(1,1)"], setup_sweep_name=setup_sweep)
    unit = (getattr(sol, "units_sweeps", {}) or {}).get("Freq") or "GHz"
    scale = {"Hz": 1e-9, "kHz": 1e-6, "MHz": 1e-3, "GHz": 1.0}[unit]
    f = [x * scale for x in sol.primary_sweep_values]
    re_, im_ = _col(sol, "S(1,1)", "real"), _col(sol, "S(1,1)", "imag")
    with open(OUT / "s11.csv", "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["f_GHz", "re", "im"])
        w.writerows(zip(f, re_, im_))
'''

GAIN = '''
    # ---- far field (best effort: S11 above is already saved)
    try:
        make_sphere = getattr(hfss, "insert_infinite_sphere", None) or hfss.create_infinite_sphere
        make_sphere(phi_start=0, phi_stop=360, phi_step=2, theta_start=0, theta_stop=180, theta_step=2,
                    units="deg", name="Inf")
        rows = []
        pat_rows = []
        for fr in FIELDS:
            sd = hfss.post.get_far_field_data(expressions="dB(GainTotal)", setup_sweep_name=f"Setup1 : {fsweep.name}",
                                              domain="Inf", sweeps={"Freq": [f"{fr}GHz"], "Theta": ["All"], "Phi": ["All"]})
            # get_expression_data ne renvoie qu'une tranche (Phi fixe) -> lire le tableau complet (toutes directions)
            try:
                import numpy as _np
                arr = _np.asarray(sd._solutions_real["dB(GainTotal)"], dtype=float)
                names = list(sd._sweeps_names)
                i = int(arr[:, -1].argmax())
                row = {n: arr[i, k] for k, n in enumerate(names)}
                rows.append((fr, float(arr[i, -1]), row.get("Theta", float("nan")), row.get("Phi", float("nan"))))
                # diagramme complet (toutes directions) pour tracer les coupes de rayonnement
                it, ip = names.index("Theta"), names.index("Phi")
                pat_rows.extend((fr, float(r[it]), float(r[ip]), float(r[-1])) for r in arr)
            except Exception:
                rows.append((fr, max(_col(sd, "dB(GainTotal)", "real")), float("nan"), float("nan")))
        if pat_rows:
            with open(OUT / "patterns.csv", "w", newline="") as fh:
                w = csv.writer(fh)
                w.writerow(["f_GHz", "theta_deg", "phi_deg", "gain_dBi"])
                w.writerows(pat_rows)
        with open(OUT / "gain.csv", "w", newline="") as fh:
            w = csv.writer(fh)
            w.writerow(["f_GHz", "peak_gain_dBi", "theta_deg", "phi_deg"])
            w.writerows(rows)
    except Exception as e:  # inspect fields manually in AEDT: Results > Create Far Fields Report
        (OUT / "gain_error.txt").write_text(repr(e))
'''

FOOTER_END = '''
    hfss.save_project()
finally:
    try:
        hfss.release_desktop(close_projects=True, close_desktop=True)
    except Exception:
        pass
'''


def _v(t) -> str:
    return "[" + ", ".join(f"{x:.6f}" for x in t) + "]"


def emit(m: Model) -> str:
    L = [HEADER]
    a = L.append
    for name, (er, tand) in m.materials.items():
        a(f'    mat = hfss.materials.add_material("{name}")')
        a(f"    mat.permittivity = {er}")
        a(f"    mat.dielectric_loss_tangent = {tand}")
    for s in m.solids:
        if isinstance(s, Box):
            size = tuple(h - l for l, h in zip(s.lo, s.hi))
            a(f'    hfss.modeler.create_box({_v(s.lo)}, {_v(size)}, name="{s.name}", material="{s.material}")')
        elif isinstance(s, Cyl):
            a(f'    hfss.modeler.create_cylinder("Z", {_v((s.xc, s.yc, s.z0))}, {s.r:.6f}, {s.z1 - s.z0:.6f}, '
              f'num_sides=0, name="{s.name}", material="{s.material}")')
    for b in m.booleans:
        if b.op == "subtract":
            a(f'    hfss.modeler.subtract("{b.target}", {b.tools!r}, keep_originals=False)')
        else:
            a(f"    hfss.modeler.unite({[b.target] + b.tools!r})")
    p = m.port
    a(f'    hfss.modeler.create_rectangle("{p.plane}", {_v(p.origin)}, {_v(p.sizes)}, name="port_sheet")')
    a("    _ax = getattr(hfss, 'axis_directions', None) or getattr(hfss, 'AxisDir', None)")
    a("    if _ax is None:")
    a("        from ansys.aedt.core.generic.constants import Gravity as _ax")
    a("    try:")
    a(f'        hfss.lumped_port(assignment="port_sheet", integration_line=_ax.ZPos, '
      f'impedance={p.z0}, name="{p.name}", renormalize=True)')
    a("    except TypeError:                                  # pyaedt < 0.9")
    a(f'        hfss.create_lumped_port_to_sheet("port_sheet", axisdir=_ax.ZPos, '
      f'impedance={p.z0}, portname="{p.name}", renorm=True)')
    pad = m.air_pad
    a("    # ---- open region (lambda/4 at the lowest frequency) + radiation boundary")
    a("    if hasattr(hfss.modeler, 'create_air_region'):")
    a(f"        region = hfss.modeler.create_air_region({pad:.4f}, {pad:.4f}, {pad:.4f}, {pad:.4f}, {pad:.4f}, {pad:.4f}, is_percentage=False)")
    a("    else:")
    a(f"        region = hfss.modeler.create_region([{pad:.4f}] * 6, 'Absolute Offset')")
    a("    hfss.assign_radiation_boundary_to_objects(region.name)")
    a("    # ---- setup + interpolating sweep")
    a('    setup = hfss.create_setup("Setup1")')
    a(f'    setup.props["Frequency"] = "{m.f0:.6f}GHz"')
    a('    setup.props["MaxDeltaS"] = 0.02')
    a('    setup.props["MaximumPasses"] = 20')
    a("    setup.update()")
    a(f'    sweep = hfss.create_linear_count_sweep("Setup1", "GHz", {m.fmin:.6f}, {m.fmax:.6f}, {m.npts}, '
      f'sweep_type="Interpolating")')
    if m.fields_ghz:
        f1, f2, n = m.fields_ghz[0], m.fields_ghz[-1], len(m.fields_ghz)
        if n == 1:
            f2, n = f1 + 0.001, 2
        a(f'    fsweep = hfss.create_linear_count_sweep("Setup1", "GHz", {f1}, {f2}, {n}, '
          f'sweep_type="Discrete", save_fields=True)')
        a(f"    FIELDS = {list(m.fields_ghz)!r}")
    a('    hfss.analyze_setup("Setup1")')
    a(FOOTER)
    if m.fields_ghz:
        a(GAIN)
    a(FOOTER_END)
    return "\n".join(L)
